package com.chain.executor

import java.sql.Connection
import java.sql.DriverManager
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.LinkedBlockingQueue
import kotlin.reflect.KClass
import kotlin.reflect.full.createInstance
import kotlin.reflect.full.memberFunctions

// Connection pool for contract state persistence
class ConnectionPool(private val url: String, private val poolSize: Int = 5) {
    private val connections = LinkedBlockingQueue<Connection>(poolSize)
    private val activeContracts = ConcurrentHashMap<String, ContractMetadata>()

    init {
        repeat(poolSize) {
            connections.offer(DriverManager.getConnection(url))
        }
    }

    fun acquire(): Connection = connections.take()
    fun release(conn: Connection) { connections.offer(conn) }

    fun registerContract(id: String, meta: ContractMetadata) {
        activeContracts[id] = meta
    }

    fun getContractMeta(id: String): ContractMetadata? = activeContracts[id]
}

data class ContractMetadata(
    val contractId: String,
    val className: String,
    val version: Int,
    val allowedMethods: Set<String>
)

// Base contract interface
interface SmartContract {
    fun initialize(params: Map<String, Any>): Boolean
    fun getState(): Map<String, Any>
}

// Registry of approved contract base classes
object ContractRegistry {
    private val approvedPackages = setOf(
        "com.chain.contracts",
        "com.chain.executor"
    )

    private val blockedMethods = setOf(
        "exec", "runtime", "processBuilder",
        "getRuntime", "loadLibrary"
    )

    fun isApprovedPackage(className: String): Boolean {
        return approvedPackages.any { className.startsWith(it) }
    }

    fun isMethodBlocked(methodName: String): Boolean {
        return blockedMethods.any { methodName.lowercase().contains(it) }
    }
}

// Contract execution engine
class ContractExecutor(private val pool: ConnectionPool) {

    private val contractCache = ConcurrentHashMap<String, Any>()

    fun deployContract(contractId: String, className: String, allowedMethods: Set<String>): Result<String> {
        // Validate the class is from an approved package
        if (!ContractRegistry.isApprovedPackage(className)) {
            return Result.failure(SecurityException("Class $className not from approved package"))
        }

        val meta = ContractMetadata(contractId, className, 1, allowedMethods)
        pool.registerContract(contractId, meta)

        return Result.success("Contract $contractId deployed")
    }

    fun invokeContract(contractId: String, methodName: String, args: Map<String, Any>): Result<Any?> {
        val meta = pool.getContractMeta(contractId)
            ?: return Result.failure(IllegalStateException("Contract not found: $contractId"))

        // Check method is allowed per contract metadata
        if (methodName !in meta.allowedMethods) {
            return Result.failure(SecurityException("Method $methodName not in allowed set"))
        }

        // Check method is not in global blocklist
        if (ContractRegistry.isMethodBlocked(methodName)) {
            return Result.failure(SecurityException("Method $methodName is blocked"))
        }

        return executeReflective(meta.className, methodName, args)
    }

    private fun executeReflective(className: String, methodName: String, args: Map<String, Any>): Result<Any?> {
        try {
            val instance = contractCache.getOrPut(className) {
                val kClass = Class.forName(className).kotlin
                kClass.createInstance()
            }

            val kClass = instance::class
            val method = kClass.memberFunctions.find { it.name == methodName }
                ?: return Result.failure(NoSuchMethodException("Method $methodName not found"))

            // Persist invocation to connection pool
            val conn = pool.acquire()
            try {
                logInvocation(conn, className, methodName)
            } finally {
                pool.release(conn)
            }

            val result = when (method.parameters.size) {
                1 -> method.call(instance)
                2 -> method.call(instance, args)
                else -> method.call(instance, *args.values.toTypedArray())
            }

            return Result.success(result)
        } catch (e: Exception) {
            return Result.failure(e)
        }
    }

    private fun logInvocation(conn: Connection, className: String, methodName: String) {
        val stmt = conn.prepareStatement(
            "INSERT INTO contract_log (class_name, method_name, timestamp) VALUES (?, ?, ?)"
        )
        stmt.setString(1, className)
        stmt.setString(2, methodName)
        stmt.setLong(3, System.currentTimeMillis())
        stmt.executeUpdate()
        stmt.close()
    }

    // Upgrade mechanism: allows re-registering with a new class
    fun upgradeContract(contractId: String, newClassName: String): Result<String> {
        val existing = pool.getContractMeta(contractId)
            ?: return Result.failure(IllegalStateException("Contract not found"))

        // Validate the NEW class is also from an approved package
        if (!ContractRegistry.isApprovedPackage(newClassName)) {
            return Result.failure(SecurityException("Upgrade class $newClassName not from approved package"))
        }

        // Upgrade preserves the allowed methods from original deployment
        val upgraded = existing.copy(className = newClassName, version = existing.version + 1)
        pool.registerContract(contractId, upgraded)
        contractCache.remove(existing.className)

        return Result.success("Contract upgraded to v${upgraded.version}")
    }
}

// Example contract in approved package
class TokenContract : SmartContract {
    private var balances = mutableMapOf<String, Long>()

    override fun initialize(params: Map<String, Any>): Boolean {
        balances["treasury"] = params["supply"] as? Long ?: 1000000L
        return true
    }

    override fun getState(): Map<String, Any> = balances.toMap()

    fun transfer(args: Map<String, Any>): Boolean {
        val from = args["from"] as? String ?: return false
        val to = args["to"] as? String ?: return false
        val amount = args["amount"] as? Long ?: return false
        val balance = balances.getOrDefault(from, 0L)
        if (balance < amount) return false
        balances[from] = balance - amount
        balances[to] = balances.getOrDefault(to, 0L) + amount
        return true
    }
}
